package com.zoro.zoromart.dao;
import java.sql.*;import java.util.*;import java.math.BigDecimal;
/** JDBC persistence for marketplace listings. */
public class ProductDAO {private final Connection c;public ProductDAO(Connection c){this.c=c;}private Map<String,Object> row(ResultSet r)throws SQLException{Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong("id"));m.put("sellerId",r.getLong("seller_id"));m.put("sellerName",r.getString("seller_name"));m.put("name",r.getString("name"));m.put("description",r.getString("description"));m.put("price",r.getBigDecimal("price"));m.put("stockQty",r.getInt("stock_qty"));m.put("category",r.getString("category"));m.put("imageUrl",r.getString("image_url"));return m;}private static final String SELECT="SELECT p.*,u.name seller_name FROM products p JOIN users u ON p.seller_id=u.id";public List<Map<String,Object>> search(String q,String category)throws SQLException{String sql=SELECT+" WHERE p.active=TRUE AND (?='' OR LOWER(p.name) LIKE ? OR LOWER(p.description) LIKE ?) AND (?='' OR p.category=?) ORDER BY p.created_at DESC";try(PreparedStatement p=c.prepareStatement(sql)){String k=q==null?"":q.toLowerCase();String cat=category==null?"":category;p.setString(1,k);p.setString(2,"%"+k+"%");p.setString(3,"%"+k+"%");p.setString(4,cat);p.setString(5,cat);try(ResultSet r=p.executeQuery()){List<Map<String,Object>> a=new ArrayList<>();while(r.next())a.add(row(r));return a;}}}public Map<String,Object> get(long id)throws SQLException{try(PreparedStatement p=c.prepareStatement(SELECT+" WHERE p.id=? AND p.active=TRUE")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?row(r):null;}}}public long create(long seller,String name,String desc,BigDecimal price,int stock,String category,String image)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO products(seller_id,name,description,price,stock_qty,category,image_url) VALUES(?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,seller);p.setString(2,name);p.setString(3,desc);p.setBigDecimal(4,price);p.setInt(5,stock);p.setString(6,category);p.setString(7,image);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}public boolean update(long id,long seller,String name,String desc,BigDecimal price,int stock,String category,String image)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE products SET name=?,description=?,price=?,stock_qty=?,category=?,image_url=?,active=TRUE WHERE id=? AND seller_id=?")){p.setString(1,name);p.setString(2,desc);p.setBigDecimal(3,price);p.setInt(4,stock);p.setString(5,category);p.setString(6,image);p.setLong(7,id);p.setLong(8,seller);return p.executeUpdate()>0;}}public boolean delete(long id,long seller,boolean admin)throws SQLException{String sql=admin?"UPDATE products SET active=FALSE WHERE id=?":"UPDATE products SET active=FALSE WHERE id=? AND seller_id=?";try(PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,id);if(!admin)p.setLong(2,seller);return p.executeUpdate()>0;}}public List<Map<String,Object>> mine(long seller)throws SQLException{try(PreparedStatement p=c.prepareStatement(SELECT+" WHERE p.seller_id=? AND p.active=TRUE ORDER BY p.id DESC")){p.setLong(1,seller);try(ResultSet r=p.executeQuery()){List<Map<String,Object>> a=new ArrayList<>();while(r.next())a.add(row(r));return a;}}}}
